<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import Icon from './components/Icon.vue'; import Avatar from './components/Avatar.vue'; import Login from './components/Login.vue';
import Dashboard from './pages/Dashboard.vue'; import Occupancy from './pages/Occupancy.vue'; import Employees from './pages/Employees.vue'; import Rooms from './pages/Rooms.vue'; import Permissions from './pages/Permissions.vue'; import Control from './pages/Control.vue'; import Events from './pages/Events.vue'; import Reports from './pages/Reports.vue'; import Settings from './pages/Settings.vue'; import Directories from './pages/Directories.vue'; import Accounts from './pages/Accounts.vue';
import { user, config, toasts, busy, loadError, ready, events, canEdit, canControl, refresh, restore, logout, notify } from './store.js';
import { ROLES } from './domain.js';
const page = ref(location.hash.slice(1) || 'dashboard'), mobileMenu = ref(false);
const navMedia = typeof window !== 'undefined' ? window.matchMedia('(max-width: 767px)') : null;
const mobile = ref(navMedia?.matches || false);
function updateMobile() { mobile.value = navMedia?.matches || false; if (!mobile.value) mobileMenu.value = false; }
function menuKey(event) { if (event.key === 'Escape') mobileMenu.value = false; }
const allNav = [ { id: 'dashboard', name: 'Обзор системы', icon: 'dashboard' }, { id: 'occupancy', name: 'Занятость помещений', icon: 'building' }, { id: 'control', name: 'Имитация прохода', icon: 'scan', roles: ['admin', 'security'] }, { section: 'УПРАВЛЕНИЕ' }, { id: 'employees', name: 'Сотрудники', icon: 'users' }, { id: 'rooms', name: 'Помещения', icon: 'rooms' }, { id: 'permissions', name: 'Права доступа', icon: 'key', roles: ['admin'] }, { id: 'directories', name: 'Справочники', icon: 'folder', roles: ['admin'] }, { section: 'МОНИТОРИНГ' }, { id: 'events', name: 'Журнал событий', icon: 'events' }, { id: 'reports', name: 'Отчёты', icon: 'reports' }, { id: 'accounts', name: 'Пользователи', icon: 'shield', roles: ['admin'] } ];
const navigation = computed(() => allNav.filter(x => !x.roles || x.roles.includes(user.value?.role)));
const validPage = computed(() => navigation.value.some(x => x.id === page.value) || page.value === 'settings' && canEdit.value);
const views = { dashboard: Dashboard, occupancy: Occupancy, employees: Employees, rooms: Rooms, permissions: Permissions, control: Control, events: Events, reports: Reports, settings: Settings, directories: Directories, accounts: Accounts };
const alerts = computed(() => events.value.filter(e => e.result === 'denied' && !e.reviewed).length);
function navigate(id) { page.value = id; location.hash = id; mobileMenu.value = false; }
function hashChanged() { page.value = location.hash.slice(1) || 'dashboard'; mobileMenu.value = false; }
async function reload() { try { await refresh(); notify('Данные обновлены.'); } catch {} }
let interval;
onMounted(() => { restore(); navMedia?.addEventListener('change', updateMobile); window.addEventListener('keydown', menuKey); window.addEventListener('hashchange', hashChanged); interval = setInterval(() => { if (user.value && ready.value && document.visibilityState === 'visible' && !busy.value) refresh().catch(() => {}); }, 30000); });
onUnmounted(() => { navMedia?.removeEventListener('change', updateMobile); window.removeEventListener('keydown', menuKey); window.removeEventListener('hashchange', hashChanged); clearInterval(interval); });
watch(user, () => { if (user.value && !validPage.value) navigate('dashboard'); });
</script>
<template><Login v-if="!user" /><div v-else class="app-shell"><div v-if="mobileMenu" class="nav-backdrop" @click="mobileMenu = false"></div><aside id="sidebar-navigation" :inert="mobile && !mobileMenu" class="sidebar" :class="{ open: mobileMenu }"><a href="#dashboard" class="brand" @click.prevent="navigate('dashboard')"><span class="brand-mark"><Icon name="rooms" :size="28" /></span><div>рубеж<span>УПРАВЛЕНИЕ ДОСТУПОМ</span></div></a><div class="workspace-label"><span class="workspace-icon"><Icon name="building" :size="19" /></span><div><strong>Моя организация</strong><small>Рабочее пространство</small></div><Icon name="lock" :size="13" /></div><nav class="main-nav" aria-label="Основная навигация"><template v-for="(item, index) in navigation" :key="item.id || index"><span v-if="item.section" class="nav-section">{{ item.section }}</span><a v-else :href="`#${item.id}`" :class="{ active: page === item.id }" :aria-current="page === item.id ? 'page' : undefined" @click.prevent="navigate(item.id)"><Icon :name="item.icon" :size="19" /><span>{{ item.name }}</span><span v-if="item.id === 'events' && alerts" class="nav-count">{{ alerts }}</span></a></template></nav><div class="sidebar-bottom"><div class="sidebar-status"><span class="pulse-dot"></span><div>{{ loadError ? 'Ошибка подключения' : ready ? 'Система подключена' : 'Подключение…' }}<small>Рабочее пространство</small></div></div><a v-if="canEdit" href="#settings" :class="{ active: page === 'settings' }" @click.prevent="navigate('settings')"><Icon name="settings" :size="19" />Настройки</a><div class="sidebar-user"><Avatar :person="user" size="sm" /><div><strong>{{ user.fullName }}</strong><small>{{ ROLES[user.role] }}</small></div><button class="icon-button" aria-label="Выйти из системы" title="Выйти" @click="logout"><Icon name="logout" :size="17" /></button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-only" aria-label="Открыть меню" :aria-expanded="mobileMenu" aria-controls="sidebar-navigation" @click="mobileMenu = !mobileMenu"><Icon name="menu" /></button><Icon name="building" :size="16" /><span>Моя организация</span><Icon name="right" :size="13" /><strong>{{ page === 'settings' ? 'Настройки' : navigation.find(x => x.id === page)?.name || 'Обзор системы' }}</strong></div><div class="topbar-right"><span class="connection-indicator"><span class="dot" :class="{ bad: loadError }"></span>{{ loadError ? 'Нет подключения' : 'Система доступа' }}</span><span class="topbar-divider"></span><button class="icon-button" title="Журнал нарушений" aria-label="Журнал нарушений" @click="navigate('events')"><Icon name="alert" :size="19" /><i v-if="alerts" class="notification-dot"></i></button></div></header><main class="main-content"><div v-if="loadError" class="alert-box sync-alert" role="alert"><Icon name="warning" /><div><strong>Не удалось обновить данные</strong><p>{{ loadError }}</p></div><button class="button small" :disabled="busy" @click="reload">Повторить</button></div><div v-if="!ready && !(page === 'settings' && canEdit)" class="empty-state"><Icon :name="busy ? 'loader' : 'database'" :size="38" :class="{ spin: busy }" /><h2>{{ busy ? 'Загружаем данные…' : 'Нет подключения к данным' }}</h2><p>Проверьте подключение и настройки доступа.</p><button v-if="!busy" class="button" @click="reload">Повторить подключение</button><button v-if="canEdit" class="text-button" @click="navigate('settings')">Открыть настройки</button></div><component :is="views[validPage ? page : 'dashboard']" v-else :key="`${config.mode}:${page}`" @navigate="navigate" /></main><footer class="app-footer"><span>Рубеж <span class="muted">/ Информационная система управления доступом</span></span><span>Учебный проект <span class="footer-dot">·</span> Время МСК</span></footer></div></div><div class="toast-stack" aria-live="polite"><div v-for="toast in toasts" :key="toast.id" class="toast" :class="toast.kind"><Icon :name="toast.kind === 'error' ? 'error' : 'success'" :size="19" /><span>{{ toast.message }}</span></div></div></template>

